// Deterministic builder for schema-field-map.json.
// actualFields are pulled verbatim from actual-packet-fields.json (ground truth,
// regenerated by tests/gen-actual-fields.mjs). specFields come from the phase
// schema YAMLs under runtime/v7/<phase>/schemas/. mappedFields pairs each spec
// field that has an engine counterpart; specOnlyFields are spec fields the engine
// never emits. Run: node parity/build-schema-field-map.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const actual = JSON.parse(
  readFileSync(join(here, "actual-packet-fields.json"), "utf8"),
);

