const RUNTIME_ORDER = [
  "knowledge",
  "continuity",
  "relationship",
  "meaning",
  "emotion",
  "need",
  "thought",
  "decision",
  "behavior",
  "expression",
  "language",
];

const packets = {};
for (const rt of RUNTIME_ORDER) {
  const spec = specData[rt];
  const actualFields = actual.packets[rt].actualFields;
  const actualSet = new Set(actualFields);
  const mapped = [];
  const specOnly = [];
  for (const sf of spec.specFields) {
    const target = spec.mapped[sf];
    if (target && actualSet.has(target)) {
      mapped.push({ spec: sf, actual: target });
    } else {
      specOnly.push(sf);
    }
  }
  const mappedTargets = new Set(mapped.map((m) => m.actual));
  const engineOnly = actualFields.filter((f) => !mappedTargets.has(f));
  packets[rt] = {
    runtimeVersion: actual.packets[rt].runtimeVersion,
    specSchema: spec.specSchema,
    actualFields,
    specFields: spec.specFields,
    mappedFields: mapped,
    specOnlyFields: specOnly,
    engineOnlyFields: engineOnly,
  };
}

const out = {
  meta: {
    artifact: "schema-field-map",
    purpose:
      "Per-packet map from spec schema content fields to the fields the engine actually emits in packet.data. actualFields are ground truth from actual-packet-fields.json (never hand-edit; regenerate via tests/gen-actual-fields.mjs). Rebuild this file with parity/build-schema-field-map.mjs.",
    categories: {
      actualFields:
        "Content field names observed in packet.data across all fixtures (ground truth).",
      specFields:
        "Content field names declared in the phase schema (envelope fields excluded).",
      mappedFields:
        "Spec field -> actual field pairs where the engine emits a counterpart.",
      specOnlyFields:
        "Spec fields with no engine counterpart (spec surface not realized).",
      engineOnlyFields:
        "Actual fields with no spec counterpart (engine emits beyond spec).",
    },
    generator: "parity/build-schema-field-map.mjs",
    source: "actual-packet-fields.json + runtime/v7/<phase>/schemas/*.yaml",
  },
  packets,
};

writeFileSync(
  join(here, "schema-field-map.json"),
  JSON.stringify(out, null, 2) + "\n",
);
console.log("wrote schema-field-map.json");
for (const rt of RUNTIME_ORDER) {
  const p = packets[rt];
  console.log(
    `  ${rt}: actual=${p.actualFields.length} spec=${p.specFields.length} mapped=${p.mappedFields.length} specOnly=${p.specOnlyFields.length} engineOnly=${p.engineOnlyFields.length}`,
  );
}
